-- Louisiana had two stops.
--
-- One dropped: Bloody Mary's Haunted Museum, forty-five metres from the copy
-- already here.
--
-- Thirteen internal proximity flags, all of them the French Quarter being the
-- French Quarter — St Louis Cemetery No. 1 holds both Marie Laveau's tomb and
-- the pyramid Nicolas Cage built for himself, and they are twenty-three metres
-- apart.
--
-- Tennessee, Alabama and Mississippi are Central time; so are Illinois,
-- Wisconsin and Louisiana. No county exceptions in any of the six.
--
-- 149 stops.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('New Orleans Historic Voodoo Museum', 'new-orleans-historic-voodoo-museum', 'folklore', 29.95981, -90.06379, 'New Orleans', 'LA', 'A compact French Quarter museum devoted to New Orleans Voodoo history, ritual objects, altars, art and local traditions. It is one of the city''s longest-running visitor sites focused specifically on Voodoo.', 'open', 'https://voodoomuseum.com/', null, 'America/Chicago', now()),
  ('Museum of Death New Orleans', 'museum-of-death-new-orleans', 'museums', 29.9559, -90.0698, 'New Orleans', 'LA', 'This macabre museum displays material connected with funerary practices, crime history, forensic subjects and death culture. The subject matter can be graphic, so it is best treated as an adult-oriented OddWay museum stop.', 'open', 'https://www.museumofdeath.net/', null, 'America/Chicago', now()),
  ('New Orleans Pharmacy Museum', 'new-orleans-pharmacy-museum', 'museums', 29.95605, -90.0649, 'New Orleans', 'LA', 'Housed in an early nineteenth-century apothecary, the museum preserves antique medicines, surgical tools, patent remedies and pharmacy equipment. Its collection includes objects that show how strange and dangerous medicine could be before modern regulation.', 'limited', 'https://pharmacymuseum.org/', null, 'America/Chicago', now()),
  ('Marie Laveau''s House of Voodoo', 'marie-laveaus-house-of-voodoo', 'folklore', 29.95824, -90.06575, 'New Orleans', 'LA', 'This Bourbon Street shop and spiritual center is named for New Orleans Voodoo figure Marie Laveau and includes altars, spiritual supplies and Voodoo-related material. Readings and spiritual services may be available separately from normal shop access.', 'open', 'https://marielaveauvoodoo.com/', null, 'America/Chicago', now()),
  ('Voodoo Spiritual Temple', 'voodoo-spiritual-temple', 'folklore', 29.96854, -90.06407, 'New Orleans', 'LA', 'Established in 1990, the Voodoo Spiritual Temple presents traditional West African-influenced spiritual and herbal practices while working to correct misconceptions about Voodoo. Its current location is 1428 N. Rampart Street; hours are flexible, so check ahead.', 'limited', 'https://voodoospiritualtemple.org/', null, 'America/Chicago', now()),
  ('Voodoo Authentica Cultural Center & Collection', 'voodoo-authentica-cultural-center-collection', 'folklore', 29.95919, -90.06277, 'New Orleans', 'LA', 'Voodoo Authentica combines a spiritual shop, cultural center and collection of works made by practitioners and artists connected with New Orleans Voodoo. It also hosts educational and ceremonial programming at selected times.', 'open', 'https://www.voodoauthentica.com/', null, 'America/Chicago', now()),
  ('St. Louis Cemetery No. 1', 'st-louis-cemetery-no-1', 'weird-history', 29.95936, -90.07144, 'New Orleans', 'LA', 'New Orleans'' oldest surviving municipal cemetery is a dense landscape of above-ground tombs tied to some of the city''s best-known historical and supernatural stories. Public entry is controlled through authorized tours, so do not expect unrestricted walk-in access.', 'limited', 'https://nolacatholiccemeteries.org/st-louis-cemetery-1', null, 'America/Chicago', now()),
  ('Marie Laveau Tomb — St. Louis Cemetery No. 1', 'marie-laveau-tomb-st-louis-cemetery-no-1', 'folklore', 29.95908, -90.07139, 'New Orleans', 'LA', 'The Glapion family tomb is widely associated with Marie Laveau and has become one of the most visited graves in New Orleans. It lies inside St. Louis Cemetery No. 1, so access is only through the cemetery''s authorized visitor system.', 'limited', 'https://nolacatholiccemeteries.org/st-louis-cemetery-1', null, 'America/Chicago', now()),
  ('Nicolas Cage Pyramid Tomb', 'nicolas-cage-pyramid-tomb', 'roadside-oddities', 29.95903, -90.07116, 'New Orleans', 'LA', 'Actor Nicolas Cage purchased cemetery plots and built a stark nine-foot pyramid mausoleum marked with the Latin phrase ''Omnia Ab Uno.'' It is inside St. Louis Cemetery No. 1 and can only be seen through lawful cemetery access.', 'limited', 'https://nolacatholiccemeteries.org/st-louis-cemetery-1', null, 'America/Chicago', now()),
  ('Cypress Grove Cemetery', 'cypress-grove-cemetery', 'weird-history', 29.97954, -90.11106, 'New Orleans', 'LA', 'Founded in 1840, Cypress Grove is known for elaborate above-ground tombs and large society mausoleums built by New Orleans fire companies. Visit only during posted cemetery hours and treat active gravesites respectfully.', 'limited', 'https://lcb.la.gov/cemetery-listings/', null, 'America/Chicago', now()),
  ('Metairie Cemetery', 'metairie-cemetery', 'weird-history', 29.98401, -90.11811, 'New Orleans', 'LA', 'The cemetery occupies the oval footprint of a former racetrack and contains some of Louisiana''s most elaborate mausoleums and funerary sculpture. Its architecture, political burials and unusual tombs make it one of the state''s strongest cemetery stops.', 'limited', 'https://www.lakelawnmetairie.com/cemetery/metairie-cemetery', null, 'America/Chicago', now()),
  ('Rice Family Mausoleum', 'rice-family-mausoleum', 'roadside-oddities', 29.98391, -90.11761, 'New Orleans', 'LA', 'The Rice family mausoleum in Metairie Cemetery is a striking Egyptian Revival tomb whose severe geometry stands out among the surrounding monuments. It is a distinct architectural target within the cemetery.', 'limited', 'https://www.lakelawnmetairie.com/cemetery/metairie-cemetery', null, 'America/Chicago', now()),
  ('Moriarty Monument', 'moriarty-monument', 'roadside-oddities', 29.9825, -90.1145, 'New Orleans', 'LA', 'This towering monument in Metairie Cemetery was commissioned by Mary Moriarty in memory of her husband and rises dramatically above neighboring tombs. Its scale makes it one of the cemetery''s easiest landmarks to recognize.', 'limited', 'https://www.lakelawnmetairie.com/cemetery/metairie-cemetery', null, 'America/Chicago', now()),
  ('Holt Cemetery', 'holt-cemetery', 'weird-history', 29.98455, -90.10482, 'New Orleans', 'LA', 'Holt Cemetery is unusual in New Orleans for its mostly in-ground burials, handmade markers and intensely personal memorial decorations. It remains an active cemetery and should be visited only during city-posted hours.', 'limited', 'https://nola.gov/cemeteries/', null, 'America/Chicago', now()),
  ('St. Roch Cemetery No. 1 and Chapel', 'st-roch-cemetery-no-1-and-chapel', 'folklore', 29.9754, -90.0525, 'New Orleans', 'LA', 'The nineteenth-century St. Roch Chapel became associated with healing petitions, and visitors historically left prosthetics, crutches and small offerings of thanks. The chapel and cemetery remain religious spaces, so visit quietly and during lawful access hours.', 'limited', 'https://nolacatholiccemeteries.org/', null, 'America/Chicago', now()),
  ('Tomb of the Unknown Slave', 'tomb-of-the-unknown-slave', 'roadside-oddities', 29.9653, -90.0663, 'New Orleans', 'LA', 'A small memorial outside St. Augustine Church honors unnamed enslaved people who died in New Orleans. The marker is a compact but powerful physical stop tied to the city''s history of slavery and remembrance.', 'open', 'https://staugchurch.org/', null, 'America/Chicago', now()),
  ('LaLaurie Mansion', 'lalaurie-mansion', 'haunted', 29.9618, -90.0612, 'New Orleans', 'LA', 'The Royal Street mansion is tied to the notorious 1834 fire that exposed abuse of enslaved people in Delphine LaLaurie''s household, later generating generations of ghost stories. It is private property; view only from the public sidewalk and do not disturb occupants.', 'private', 'https://www.neworleans.com/things-to-do/history/', null, 'America/Chicago', now()),
  ('Muriel''s Jackson Square Séance Lounge', 'muriels-jackson-square-s-ance-lounge', 'haunted', 29.95843, -90.06309, 'New Orleans', 'LA', 'Muriel''s embraces the building''s ghost lore with a dedicated séance lounge and stories about former resident Pierre Antoine Lepardi Jourdan. It is an operating restaurant, so paranormal interest should remain secondary to normal guest access.', 'open', 'https://muriels.com/', null, 'America/Chicago', now()),
  ('Lafitte''s Blacksmith Shop Bar', 'lafittes-blacksmith-shop-bar', 'folklore', 29.96074, -90.06389, 'New Orleans', 'LA', 'This eighteenth-century Creole cottage is wrapped in legends linking it to pirate and smuggler Jean Lafitte. The exact extent of Lafitte''s connection is debated, but the surviving building is one of Bourbon Street''s oldest and most atmospheric landmarks.', 'open', 'https://www.lafittesblacksmithshop.com/', null, 'America/Chicago', now()),
  ('Old Absinthe House', 'old-absinthe-house', 'weird-history', 29.95537, -90.06845, 'New Orleans', 'LA', 'The Old Absinthe House has served drinks near Bourbon Street since the nineteenth century and accumulated stories involving pirates, politicians, writers and supposed secret meetings. Its surviving marble fountains and long bar history make it a classic New Orleans odd-history stop.', 'open', 'https://www.ruebourbon.com/oldabsinthehouse', null, 'America/Chicago', now()),
  ('Café Lafitte in Exile', 'caf-lafitte-in-exile', 'haunted', 29.9604, -90.0642, 'New Orleans', 'LA', 'This long-running Bourbon Street gay bar has accumulated stories of apparitions associated in local lore with writers and former patrons. It remains an active nightlife business rather than a paranormal attraction.', 'open', 'https://www.lafittes.com/', null, 'America/Chicago', now()),
  ('Napoleon House', 'napoleon-house', 'weird-history', 29.95586, -90.06507, 'New Orleans', 'LA', 'The building takes its name from an unrealized plan to shelter Napoleon Bonaparte in New Orleans after his exile. Its weathered interior, classical music tradition and layers of political lore make it unusually intact French Quarter history.', 'open', 'https://www.napoleonhouse.com/', null, 'America/Chicago', now()),
  ('Carousel Bar & Lounge', 'carousel-bar-lounge', 'roadside-oddities', 29.95435, -90.06787, 'New Orleans', 'LA', 'The Hotel Monteleone''s bar is built as a rotating carousel that slowly carries seated guests around its center. It has operated for decades and remains one of the city''s best-known pieces of functioning novelty architecture.', 'open', 'https://hotelmonteleone.com/entertainment/carousel-bar/', null, 'America/Chicago', now()),
  ('Tremé''s Petit Jazz Museum', 'trem-s-petit-jazz-museum', 'museums', 29.96693, -90.0682, 'New Orleans', 'LA', 'This small museum tells jazz history through Tremé''s musicians, neighborhoods and cultural traditions rather than through a huge institutional collection. Its intimate scale and highly local focus make it especially well suited to OddWay.', 'limited', 'https://tremejazzmuseum.com/', null, 'America/Chicago', now()),
  ('Backstreet Cultural Museum', 'backstreet-cultural-museum', 'museums', 29.96583, -90.07011, 'New Orleans', 'LA', 'Backstreet preserves Mardi Gras Indian suits, social aid and pleasure club material, jazz funeral traditions and neighborhood parade culture. The collection gives travelers a close look at traditions often seen only briefly in street processions.', 'limited', 'https://www.backstreetmuseum.org/', null, 'America/Chicago', now()),
  ('House of Dance & Feathers', 'house-of-dance-feathers', 'museums', 29.95187, -90.00428, 'New Orleans', 'LA', 'This Lower Ninth Ward community collection documents Mardi Gras Indians, second lines, social aid and pleasure clubs and neighborhood culture. It has historically operated more like a living community archive than a conventional museum, so arrange access before going.', 'limited', 'https://houseofdanceandfeathers.org/', null, 'America/Chicago', now()),
  ('The Presbytère — Mardi Gras & Katrina Exhibits', 'the-presbyt-re-mardi-gras-katrina-exhibits', 'museums', 29.95826, -90.0634, 'New Orleans', 'LA', 'The Louisiana State Museum uses the Presbytère for major exhibits on Mardi Gras and Hurricane Katrina. Costumes, parade objects and disaster-history material make this far stranger than a standard civic museum.', 'open', 'https://louisianastatemuseum.org/museum/presbytere', null, 'America/Chicago', now()),
  ('Great American Alligator Museum', 'great-american-alligator-museum', 'museums', 29.93034, -90.07575, 'New Orleans', 'LA', 'This Magazine Street museum is devoted to the American alligator in Louisiana culture, history, science and popular imagery. It turns a single animal into a focused, unusually specific museum experience.', 'open', 'https://www.gator-museum.com/', null, 'America/Chicago', now()),
  ('Museum of the Southern Jewish Experience', 'museum-of-the-southern-jewish-experience', 'museums', 29.9442, -90.0742, 'New Orleans', 'LA', 'The museum explores Jewish life across the American South through migration, small-town communities, civil rights history and regional culture. Its geographic focus makes it a distinctive counterpart to more conventional Jewish-history museums.', 'open', 'https://msje.org/', null, 'America/Chicago', now()),
  ('Dark Matter Oddities & Artisan Collective', 'dark-matter-oddities-artisan-collective', 'roadside-oddities', 29.95871, -90.06262, 'New Orleans', 'LA', 'Dark Matter specializes in taxidermy, wet specimens, fossils, Victorian ephemera, medical objects and macabre art. Inventory changes constantly, but the shop remains one of the French Quarter''s most concentrated cabinets of curiosities.', 'open', 'https://darkmatteroddities.com/', null, 'America/Chicago', now()),
  ('Hidden South — The Confessional', 'hidden-south-the-confessional', 'museums', 29.95622, -90.00146, 'Arabi', 'LA', 'Hidden South''s gallery and shop grew from photographer Brent Walker''s documentation of overlooked people, places and folk art across the South. The space functions as a compact museum-store for outsider culture and unusual regional stories.', 'open', 'https://thehiddensouth.com/', null, 'America/Chicago', now()),
  ('New Orleans Jazz Museum at the Old U.S. Mint', 'new-orleans-jazz-museum-at-the-old-us-mint', 'weird-history', 29.96136, -90.05781, 'New Orleans', 'LA', 'The former U.S. Mint now houses Louisiana State Museum collections tracing the development of jazz. Instruments, recordings and a building that once produced money create an unusual overlap of music and industrial history.', 'open', 'https://nolajazzmuseum.org/', null, 'America/Chicago', now()),
  ('Music Box Village', 'music-box-village', 'roadside-oddities', 29.96361, -90.02934, 'New Orleans', 'LA', 'Music Box Village is a walk-through environment of artist-built structures that double as playable musical instruments. Performances and public hours follow a changing calendar, so confirm an event or open day before routing there.', 'limited', 'https://musicboxvillage.com/', null, 'America/Chicago', now()),
  ('Dr. Bob Folk Art', 'dr-bob-folk-art', 'roadside-oddities', 29.9642, -90.043, 'New Orleans', 'LA', 'Local artist Dr. Bob is known for handmade signs, assemblages and the recurring ''Be Nice or Leave'' slogan. His Chartres Street studio is a dense folk-art environment rather than a conventional gallery; verify current hours before visiting.', 'limited', 'https://drbobart.net/', null, 'America/Chicago', now()),
  ('Piazza d''Italia', 'piazza-ditalia', 'roadside-oddities', 29.94798, -90.06646, 'New Orleans', 'LA', 'Designed by Charles Moore, this postmodern plaza uses bright colors, classical columns, neon and a fountain shaped around the map of Italy. It looks like a theatrical Roman ruin built for the late twentieth century.', 'open', 'https://www.tclf.org/landscapes/piazza-ditalia', null, 'America/Chicago', now()),
  ('Doullut Steamboat Houses', 'doullut-steamboat-houses', 'roadside-oddities', 29.95582, -90.02173, 'New Orleans', 'LA', 'Two Lower Ninth Ward houses were designed with towers and galleries that deliberately echo Mississippi River steamboats. They are private residences, so appreciate the architecture from public streets only.', 'roadside', 'https://www.nps.gov/nr/travel/louisiana/', null, 'America/Chicago', now()),
  ('Luling Mansion', 'luling-mansion', 'roadside-oddities', 29.9826, -90.0862, 'New Orleans', 'LA', 'This sprawling Italianate mansion was built in the 1860s for cotton merchant Florence Luling and now survives inside a later apartment complex. Its scale and secluded appearance make it a striking architectural anomaly; view only from lawful public areas.', 'roadside', 'https://www.nps.gov/nr/travel/louisiana/', null, 'America/Chicago', now()),
  ('United Fruit Company Building', 'united-fruit-company-building', 'roadside-oddities', 29.95104, -90.07055, 'New Orleans', 'LA', 'Fruit motifs carved into the facade reveal this building''s former connection to the United Fruit Company and the banana trade. The exterior is the attraction; do not treat the interior as a public museum.', 'roadside', 'https://www.atlasobscura.com/places/united-fruit-company-building', null, 'America/Chicago', now()),
  ('General Laundry Cleaners and Dyers Building', 'general-laundry-cleaners-and-dyers-building', 'roadside-oddities', 29.9687, -90.08132, 'New Orleans', 'LA', 'This Art Deco industrial building is famous for a facade decorated with oversized soap bubbles and stylized laundry imagery. It is best treated as an exterior architectural photo stop.', 'roadside', 'https://www.nps.gov/nr/', null, 'America/Chicago', now()),
  ('FLOAT House', 'float-house', 'roadside-oddities', 29.96875, -90.02152, 'New Orleans', 'LA', 'The FLOAT House was designed after Hurricane Katrina as a prototype home able to rise vertically during flooding. It remains a private residence, so OddWay visitors should view it only from the street.', 'roadside', 'https://www.makeitright.org/', null, 'America/Chicago', now()),
  ('Old Spanish Fort Site', 'old-spanish-fort-site', 'weird-history', 30.0224, -90.0842, 'New Orleans', 'LA', 'This lakefront area passed through Native American use, colonial fortification, resort development and an amusement-park era. Very little of the entertainment complex survives, making the site a layered landscape of vanished New Orleans recreation.', 'open', 'https://www.atlasobscura.com/places/old-spanish-fort', null, 'America/Chicago', now()),
  ('Congo Square', 'congo-square', 'weird-history', 29.96128, -90.06853, 'New Orleans', 'LA', 'Congo Square is historically associated with gatherings of enslaved and free people of African descent who played music, danced and traded on Sundays. The public space is foundational to histories of New Orleans music and African diasporic culture.', 'open', 'https://louisiana.edu/', null, 'America/Chicago', now()),
  ('Dew Drop Inn', 'dew-drop-inn', 'weird-history', 29.93692, -90.09164, 'New Orleans', 'LA', 'The restored Dew Drop Inn was a major twentieth-century Black music venue and hotel that hosted rhythm-and-blues pioneers. It has reopened as a hotel, bar and performance space while preserving its music-history identity.', 'open', 'https://dewdropinnnola.com/', null, 'America/Chicago', now()),
  ('New Orleans Musical Legends Park', 'new-orleans-musical-legends-park', 'roadside-oddities', 29.95585, -90.06844, 'New Orleans', 'LA', 'This compact Bourbon Street courtyard contains bronze statues honoring New Orleans musicians such as Fats Domino, Pete Fountain and Al Hirt. It is an easy public stop that turns local music history into a small sculpture garden.', 'open', 'https://www.neworleansmusicallegends.com/', null, 'America/Chicago', now()),
  ('The Singing Oak', 'the-singing-oak', 'roadside-oddities', 29.9859, -90.0902, 'New Orleans', 'LA', 'Wind chimes tuned to a pentatonic scale hang high in a live oak near Big Lake in City Park, creating shifting music whenever the breeze moves through the branches. The installation is outdoors and freely viewable during park access.', 'open', 'https://neworleanscitypark.org/', null, 'America/Chicago', now()),
  ('Tree of Life — Audubon Park', 'tree-of-life-audubon-park', 'roadside-oddities', 29.921, -90.1294, 'New Orleans', 'LA', 'This enormous live oak is one of the most recognizable trees in Audubon Park, with massive low branches spreading close to the ground. Its age, scale and sculptural form make it a strong natural OddWay landmark.', 'open', 'https://audubonnatureinstitute.org/audubon-park', null, 'America/Chicago', now()),
  ('National Shrine of Blessed Francis Xavier Seelos', 'national-shrine-of-blessed-francis-xavier-seelos', 'roadside-oddities', 29.92907, -90.07454, 'New Orleans', 'LA', 'The shrine preserves relics and a museum connected with nineteenth-century priest Francis Xavier Seelos, including objects tied to his ministry during a yellow-fever epidemic. It is an active religious site rather than a curiosity museum, so visit respectfully.', 'open', 'https://seelos.org/', null, 'America/Chicago', now()),
  ('Starting Point of the First New Orleans Mardi Gras Parade Marker', 'starting-point-of-the-first-new-orleans-mardi-gras-parade-marker', 'weird-history', 29.94547, -90.06934, 'New Orleans', 'LA', 'A historical marker identifies the area associated with the Mistick Krewe of Comus procession of 1857, a major turning point in the development of organized Mardi Gras parades. It gives travelers a concrete point for a tradition otherwise spread across the city.', 'roadside', 'https://www.hmdb.org/', null, 'America/Chicago', now()),
  ('Mardi Gras World', 'mardi-gras-world', 'museums', 29.93483, -90.06139, 'New Orleans', 'LA', 'Blaine Kern''s working float facility lets visitors walk among oversized parade props and see how Mardi Gras floats are built and painted. Because it is both workshop and attraction, displays can change substantially between visits.', 'open', 'https://www.mardigrasworld.com/', null, 'America/Chicago', now()),
  ('New Canal Lighthouse', 'new-canal-lighthouse', 'weird-history', 30.02717, -90.11317, 'New Orleans', 'LA', 'The reconstructed lighthouse on Lake Pontchartrain interprets local navigation, storms and coastal history at the mouth of the New Basin Canal. Museum access follows posted hours even though the exterior can be seen from the lakefront.', 'limited', 'https://scienceforourcoast.org/new-canal-lighthouse/', null, 'America/Chicago', now()),
  ('Birthplace of Dixie Plaque', 'birthplace-of-dixie-plaque', 'weird-history', 29.95385, -90.06814, 'New Orleans', 'LA', 'A plaque near the French Quarter commemorates the place traditionally associated with the first performance of the song ''Dixie'' in 1859. The claim is part of a complicated performance history, but the marker gives it a fixed physical location.', 'roadside', 'https://www.hmdb.org/', null, 'America/Chicago', now()),
  ('Pitot House', 'pitot-house', 'roadside-oddities', 29.98247, -90.08687, 'New Orleans', 'LA', 'The Pitot House is a rare surviving example of a late-eighteenth-century Creole colonial country house along Bayou St. John. Guided or posted museum access is required rather than unrestricted entry.', 'limited', 'https://louisianalandmarks.org/pitot-house/', null, 'America/Chicago', now()),
  ('BK Historic House & Gardens', 'bk-historic-house-gardens', 'haunted', 29.96083, -90.06111, 'New Orleans', 'LA', 'The 1826 Beauregard-Keyes House is a preserved French Quarter residence associated with military, immigrant and literary history, along with local ghost lore. It operates as a ticketed historic house museum with scheduled programming.', 'limited', 'https://www.bkhouse.org/', null, 'America/Chicago', now()),
  ('Gallier House', 'gallier-house', 'roadside-oddities', 29.96172, -90.06132, 'New Orleans', 'LA', 'Architect James Gallier Jr. designed this 1857 townhouse with advanced-for-its-era indoor plumbing, ventilation and service spaces. Guided museum access reveals the technology hidden behind its formal French Quarter facade.', 'limited', 'https://hgghh.org/gallier-house/', null, 'America/Chicago', now()),
  ('Abita Mystery House', 'abita-mystery-house', 'roadside-oddities', 30.47741, -90.03627, 'Abita Springs', 'LA', 'A classic roadside attraction packed with homemade inventions, taxidermy, arcade machines, folk art and deliberately fake creatures. Its best-known exhibits blur museum display and prank in exactly the way OddWay is built for.', 'open', 'https://abitamysteryhouse.com/', null, 'America/Chicago', now()),
  ('Seven Sisters Oak', 'seven-sisters-oak', 'roadside-oddities', 30.3671, -90.0991, 'Mandeville', 'LA', 'This enormous live oak is recognized as one of Louisiana''s most celebrated ancient trees and is named for seven sisters connected with the property. It stands on private land, so visitors must obtain permission rather than entering uninvited.', 'private', 'https://www.lgcfinc.org/', null, 'America/Chicago', now()),
  ('Dew Drop Social & Benevolent Hall', 'dew-drop-social-benevolent-hall', 'weird-history', 30.356, -90.06226, 'Mandeville', 'LA', 'Built in 1895, the tiny wooden hall is one of the oldest surviving rural jazz venues in the country. It still hosts selected performances, making access event-dependent rather than daily.', 'limited', 'https://dewdropjazzhall.com/', null, 'America/Chicago', now()),
  ('H.J. Smith''s Sons General Store & Museum', 'hj-smiths-sons-general-store-museum', 'museums', 30.47604, -90.09427, 'Covington', 'LA', 'Behind a functioning old general store is an eclectic free museum of tools, farm equipment, household objects, weapons and regional artifacts accumulated over generations. The result feels more like a family cabinet of curiosities than a polished museum.', 'open', 'https://www.covla.com/', null, 'America/Chicago', now()),
  ('Insta-Gator Ranch', 'insta-gator-ranch', 'roadside-oddities', 30.51857, -90.0081, 'Covington', 'LA', 'This working alligator ranch offers guided visits explaining the commercial alligator industry and allows unusually close viewing of large numbers of animals. Tours are controlled experiences, so use the ranch''s reservation and operating rules.', 'limited', 'https://insta-gatorranch.com/', null, 'America/Chicago', now()),
  ('Manchac Swamp Bridge', 'manchac-swamp-bridge', 'roadside-oddities', 30.30295, -90.40581, 'Manchac', 'LA', 'Interstate 55 crosses miles of cypress swamp on one of the longest bridge structures in the United States. The experience is the drive itself; never stop on the interstate or attempt to access bridge infrastructure.', 'roadside', 'https://www.fhwa.dot.gov/', null, 'America/Chicago', now()),
  ('Frenier Cemetery', 'frenier-cemetery', 'haunted', 30.09303, -90.43274, 'LaPlace', 'LA', 'The isolated cemetery is tied to local stories about Julia Brown, a supposed folk healer whose death was later connected in legend with the devastating 1915 hurricane. The site is not a casual roadside cemetery; access is typically through authorized swamp-tour property arrangements.', 'limited', 'https://www.cajunprideswamptours.com/', null, 'America/Chicago', now()),
  ('Honey Island Swamp', 'honey-island-swamp', 'cryptids', 30.21719, -89.64969, 'Pearl River', 'LA', 'Honey Island Swamp is the setting for Louisiana''s best-known cryptid tradition, the Honey Island Swamp Monster. Explore only through lawful public-water access or established tour operators rather than trespassing into remote marshland.', 'limited', 'https://www.explorelouisiana.com/', null, 'America/Chicago', now()),
  ('Miss Pearl Giant Alligator', 'miss-pearl-giant-alligator', 'roadside-oddities', 30.37665, -89.74823, 'Pearl River', 'LA', 'A giant alligator sculpture named Miss Pearl sits outside a Pearl River business and gives the Honey Island area an appropriately oversized roadside mascot. It is a quick exterior photo stop; stay within customer or public access areas.', 'roadside', 'https://www.roadsideamerica.com/', null, 'America/Chicago', now()),
  ('Fontainebleau Sugar Mill Ruins', 'fontainebleau-sugar-mill-ruins', 'weird-history', 30.3376, -90.0381, 'Mandeville', 'LA', 'Brick ruins from Bernard de Marigny''s early nineteenth-century sugar operation survive inside Fontainebleau State Park. The industrial remains sit incongruously among the park''s oak and lakeshore landscape.', 'open', 'https://www.lastateparks.com/parks-preserves/fontainebleau-state-park', null, 'America/Chicago', now()),
  ('Fifty-Foot Wooden Alligator', 'fifty-foot-wooden-alligator', 'roadside-oddities', 30.06561, -90.48411, 'LaPlace', 'LA', 'An enormous wooden alligator sculpture has long served as a roadside landmark on Belle Terre Boulevard. Treat it as a quick exterior photo stop and do not obstruct the surrounding business property.', 'roadside', 'https://www.roadsideamerica.com/', null, 'America/Chicago', now()),
  ('Ponchatoula Giant Strawberry', 'ponchatoula-giant-strawberry', 'roadside-oddities', 30.4388, -90.4401, 'Ponchatoula', 'LA', 'A giant strawberry sculpture celebrates Ponchatoula''s identity as a strawberry-growing center and festival town. The oversized fruit is an easy downtown roadside landmark.', 'roadside', 'https://www.ponchatoulachamber.com/', null, 'America/Chicago', now()),
  ('National Hansen''s Disease Museum', 'national-hansens-disease-museum', 'weird-history', 30.21717, -91.09577, 'Carville', 'LA', 'The museum occupies part of the former national leprosarium at Carville and interprets Hansen''s disease, treatment, stigma and the lives of patients who lived there. It sits within a Louisiana National Guard installation, so visitors must follow current gate and identification procedures.', 'limited', 'https://www.hrsa.gov/hansens-disease/museum', null, 'America/Chicago', now()),
  ('Whitney Plantation', 'whitney-plantation', 'weird-history', 30.03994, -90.64908, 'Wallace', 'LA', 'Whitney Plantation is operated as a museum centered on the history and experiences of enslaved people rather than plantation nostalgia. Memorials, restored buildings and first-person historical evidence make it one of Louisiana''s most important difficult-history stops.', 'limited', 'https://www.whitneyplantation.org/', null, 'America/Chicago', now()),
  ('Laura Plantation', 'laura-plantation', 'folklore', 30.00813, -90.72533, 'Vacherie', 'LA', 'Laura preserves a Creole plantation complex and tells the intertwined histories of the Duparc-Locoul family and the people they enslaved. Folktales recorded from the region also contributed to later published Br''er Rabbit traditions.', 'limited', 'https://www.lauraplantation.com/', null, 'America/Chicago', now()),
  ('Destrehan Plantation', 'destrehan-plantation', 'weird-history', 29.94539, -90.36532, 'Destrehan', 'LA', 'Destrehan is one of the lower Mississippi River valley''s oldest documented plantation houses and interprets slavery, sugar production and the site''s long social history. Access to the historic buildings is through the operating museum.', 'limited', 'https://www.destrehanplantation.org/', null, 'America/Chicago', now()),
  ('The Myrtles Plantation', 'the-myrtles-plantation', 'haunted', 30.80369, -91.38785, 'St. Francisville', 'LA', 'The Myrtles is one of Louisiana''s most aggressively marketed haunted historic properties, with long-running legends of apparitions and a famously discussed mirror. It operates as an inn and tour attraction, so access depends on bookings and scheduled tours.', 'limited', 'https://www.myrtlesplantation.com/', null, 'America/Chicago', now()),
  ('Grace Episcopal Church Cemetery', 'grace-episcopal-church-cemetery', 'weird-history', 30.7761, -91.3869, 'St. Francisville', 'LA', 'The cemetery and church grounds are tied to the Civil War episode remembered locally as ''The Day the War Stopped,'' when opposing forces paused fighting for the burial of a Union naval officer. Visit quietly during lawful church and cemetery access.', 'limited', 'https://www.gracechurchwfp.org/', null, 'America/Chicago', now()),
  ('Rosedown Plantation State Historic Site', 'rosedown-plantation-state-historic-site', 'roadside-oddities', 30.79602, -91.37095, 'St. Francisville', 'LA', 'Rosedown preserves a large antebellum house and formal gardens while interpreting the plantation economy and enslaved labor that sustained it. The state historic site gives travelers extensive lawful access to a landscape that would otherwise be private.', 'open', 'https://www.lastateparks.com/historic-sites/rosedown-plantation-state-historic-site', null, 'America/Chicago', now()),
  ('Audubon State Historic Site — Oakley House', 'audubon-state-historic-site-oakley-house', 'weird-history', 30.79907, -91.30789, 'St. Francisville', 'LA', 'John James Audubon spent part of 1821 at Oakley while tutoring a plantation family''s daughter and working on bird studies. The preserved house and grounds connect natural-history art with the plantation world that supported his stay.', 'open', 'https://www.lastateparks.com/historic-sites/audubon-state-historic-site', null, 'America/Chicago', now()),
  ('Locust Grove State Historic Site', 'locust-grove-state-historic-site', 'weird-history', 30.83768, -91.33567, 'St. Francisville', 'LA', 'This small historic site preserves the family cemetery of Sarah Knox Taylor Davis, first wife of Jefferson Davis. Current state schedules list Locust Grove as appointment-based, so arrange access rather than arriving unannounced.', 'limited', 'https://www.lastateparks.com/historic-sites', null, 'America/Chicago', now()),
  ('Port Hudson State Historic Site', 'port-hudson-state-historic-site', 'weird-history', 30.68876, -91.28158, 'Zachary', 'LA', 'Port Hudson preserves portions of the battlefield associated with one of the longest sieges in American military history. Earthworks, museum exhibits and trails provide a concrete landscape for the 1863 campaign.', 'open', 'https://www.lastateparks.com/historic-sites/port-hudson-state-historic-site', null, 'America/Chicago', now()),
  ('Louisiana State Penitentiary Museum', 'louisiana-state-penitentiary-museum', 'weird-history', 30.94035, -91.56942, 'Angola', 'LA', 'The museum documents the history of the Louisiana State Penitentiary, better known as Angola, through prison artifacts and institutional history. Because it is connected with an active maximum-security prison complex, follow all current visitor rules and do not wander beyond designated areas.', 'limited', 'https://angolamuseum.org/', null, 'America/Chicago', now()),
  ('LSU Campus Mounds', 'lsu-campus-mounds', 'weird-history', 30.41506, -91.18222, 'Baton Rouge', 'LA', 'Two Native American earthworks on LSU''s campus are among the oldest surviving human-made structures in the region. They are fragile archaeological sites, so observe university protections and never climb, dig or disturb them.', 'open', 'https://www.lsu.edu/', null, 'America/Chicago', now()),
  ('Old Louisiana State Capitol', 'old-louisiana-state-capitol', 'roadside-oddities', 30.44694, -91.18889, 'Baton Rouge', 'LA', 'Louisiana''s Gothic Revival former capitol looks more like a castle than a conventional government building. It now operates as a political-history museum with an especially theatrical interior.', 'open', 'https://louisianaoldstatecapitol.org/', null, 'America/Chicago', now()),
  ('Louisiana State Capitol — Huey Long Assassination Site', 'louisiana-state-capitol-huey-long-assassination-site', 'weird-history', 30.45709, -91.18737, 'Baton Rouge', 'LA', 'The present capitol is tied to the 1935 shooting of Senator Huey P. Long, one of the most consequential and disputed episodes in Louisiana political history. Visitors may enter through normal security procedures; some areas can close for government operations or renovation.', 'open', 'https://house.louisiana.gov/pubinfo/', null, 'America/Chicago', now()),
  ('Huey P. Long Tomb', 'huey-p-long-tomb', 'roadside-oddities', 30.45562, -91.18763, 'Baton Rouge', 'LA', 'Huey Long''s grave sits directly in front of the Louisiana State Capitol beneath a large statue of the populist politician. The monument''s placement makes his political legacy physically dominate the approach to the building.', 'open', 'https://www.hmdb.org/', null, 'America/Chicago', now()),
  ('Oliver Pollock Sculpture', 'oliver-pollock-sculpture', 'roadside-oddities', 30.44664, -91.18838, 'Baton Rouge', 'LA', 'This unusual downtown sculpture honors Oliver Pollock, a merchant credited with helping popularize the dollar sign in American financial correspondence. It is a small public-art stop with an unexpectedly large connection to everyday symbolism.', 'open', 'https://www.atlasobscura.com/places/oliver-pollock', null, 'America/Chicago', now()),
  ('Mike the Tiger Habitat', 'mike-the-tiger-habitat', 'roadside-oddities', 30.41342, -91.18507, 'Baton Rouge', 'LA', 'LSU''s live tiger mascot inhabits a large landscaped enclosure beside Tiger Stadium. The habitat is a public-facing university landmark, but visitors should respect animal-care barriers and any temporary closure notices.', 'open', 'https://www.mikethetiger.com/', null, 'America/Chicago', now()),
  ('USS KIDD Veterans Museum', 'uss-kidd-veterans-museum', 'weird-history', 30.44434, -91.1915, 'Baton Rouge', 'LA', 'The preserved Fletcher-class destroyer USS KIDD serves as a floating museum on the Mississippi River. Ship access depends on restoration status, river conditions and museum procedures, so check the current visitor notice before going.', 'limited', 'https://www.usskidd.com/', null, 'America/Chicago', now()),
  ('Louisiana Art & Science Museum — Ancient Egyptian Gallery', 'louisiana-art-science-museum-ancient-egyptian-gallery', 'museums', 30.44641, -91.19041, 'Baton Rouge', 'LA', 'This former railroad station contains an art museum, planetarium and an Ancient Egyptian gallery with a Ptolemaic-era mummy. The mixture of astronomy, fine art and mummification makes it a surprisingly eclectic stop.', 'open', 'https://www.lasm.org/', null, 'America/Chicago', now()),
  ('Sing the River Sculpture', 'sing-the-river-sculpture', 'roadside-oddities', 30.44925, -91.19066, 'Baton Rouge', 'LA', 'The riverfront sculpture by Po Shu Wang responds to Mississippi River data with shifting light and sound. It turns the river''s changing conditions into a public sensory installation.', 'open', 'https://www.visitbatonrouge.com/', null, 'America/Chicago', now()),
  ('Plaquemine Lock State Historic Site', 'plaquemine-lock-state-historic-site', 'roadside-oddities', 30.29243, -91.23431, 'Plaquemine', 'LA', 'This early twentieth-century lock connected Bayou Plaquemine with the Mississippi River and preserves massive engineering machinery from the era of inland waterway expansion. The locally operated museum schedule can vary, so check ahead.', 'limited', 'https://www.lastateparks.com/historic-sites/plaquemine-lock-state-historic-site', null, 'America/Chicago', now()),
  ('Teddy''s Juke Joint', 'teddys-juke-joint', 'weird-history', 30.59315, -91.16818, 'Zachary', 'LA', 'Teddy''s is a decorated shotgun-house blues club covered inside with lights, memorabilia and handmade details. Live music follows a changing schedule, so it is a destination to verify before making a dedicated detour.', 'limited', 'https://www.visitbatonrouge.com/directory/teddys-juke-joint/', null, 'America/Chicago', now()),
  ('Magnolia Mound', 'magnolia-mound', 'roadside-oddities', 30.42965, -91.18894, 'Baton Rouge', 'LA', 'Magnolia Mound preserves a late-eighteenth-century Creole plantation house built with cypress and bousillage construction. Museum interpretation addresses the site''s architecture, material culture and enslaved labor.', 'limited', 'https://www.brec.org/facility/MagnoliaMound', null, 'America/Chicago', now()),
  ('Chauvin Sculpture Garden', 'chauvin-sculpture-garden', 'roadside-oddities', 29.44371, -90.59276, 'Chauvin', 'LA', 'Artist Kenny Hill transformed a bayou-side property into a dense concrete landscape of angels, self-portraits, towers and religious imagery before abruptly leaving it behind. Nicholls State University now preserves the environment as a public folk-art site.', 'open', 'https://www.nicholls.edu/folkartcenter/', null, 'America/Chicago', now()),
  ('Bayou Terrebonne Waterlife Museum', 'bayou-terrebonne-waterlife-museum', 'museums', 29.59852, -90.72041, 'Houma', 'LA', 'The museum explains life, work and environmental change along Bayou Terrebonne through fisheries, wetlands and local industries. Its focus on a disappearing coastal landscape gives it unusual relevance beyond ordinary local history.', 'open', 'https://www.houmatravel.com/', null, 'America/Chicago', now()),
  ('Laurel Valley Village', 'laurel-valley-village', 'weird-history', 29.80124, -90.77915, 'Thibodaux', 'LA', 'Laurel Valley preserves rows of historic sugar-plantation workers'' houses and support buildings in one of the largest surviving complexes of its type. Much of the property remains privately managed, so use designated visitor areas and current tour rules.', 'limited', 'https://www.lafourche.org/', null, 'America/Chicago', now()),
  ('Wetlands Acadian Cultural Center', 'wetlands-acadian-cultural-center', 'museums', 29.79619, -90.82495, 'Thibodaux', 'LA', 'This National Park Service center interprets Cajun culture, bayou life and the wetlands of the Mississippi Delta. Ranger programs and boat activities can be seasonal or scheduled, so confirm the day''s offerings.', 'limited', 'https://www.nps.gov/jela/planyourvisit/wetlands-acadian-cultural-center.htm', null, 'America/Chicago', now()),
  ('TABASCO Factory Tour & Museum', 'tabasco-factory-tour-museum', 'roadside-oddities', 29.90977, -91.90245, 'Avery Island', 'LA', 'The self-guided TABASCO experience follows pepper sauce from mash aging through bottling and includes a museum devoted to the brand''s history. The factory''s global product is still made on the same salt-dome island.', 'open', 'https://www.tabasco.com/visit-avery-island/', null, 'America/Chicago', now()),
  ('Jungle Gardens Buddha Shrine', 'jungle-gardens-buddha-shrine', 'roadside-oddities', 29.90805, -91.91613, 'Avery Island', 'LA', 'A centuries-old Buddha statue sits unexpectedly among subtropical gardens, bamboo and wildlife on Avery Island. The shrine is inside ticketed Jungle Gardens and should be treated as a contemplative site rather than a prop.', 'open', 'https://www.junglegardens.org/', null, 'America/Chicago', now()),
  ('LARC''s Acadian Village', 'larcs-acadian-village', 'museums', 30.17665, -92.09235, 'Lafayette', 'LA', 'A collection of moved and reconstructed nineteenth-century buildings forms a small village interpreting Acadian life in South Louisiana. The site also hosts seasonal events that can change normal access.', 'open', 'https://www.acadianvillage.org/', null, 'America/Chicago', now()),
  ('Vermilionville Historic Village', 'vermilionville-historic-village', 'museums', 30.21457, -91.9971, 'Lafayette', 'LA', 'Vermilionville recreates and preserves Acadian, Creole and Native cultural landscapes using historic buildings, crafts and music. Demonstrations and performances make it more immersive than a static museum.', 'open', 'https://bayouvermiliondistrict.org/vermilionville/', null, 'America/Chicago', now()),
  ('St. John Cathedral Oak', 'st-john-cathedral-oak', 'roadside-oddities', 30.22328, -92.02344, 'Lafayette', 'LA', 'The enormous live oak beside the Cathedral of St. John the Evangelist is estimated to be centuries old and spreads across much of the churchyard. Its branches form a natural architectural landmark in downtown Lafayette.', 'open', 'https://saintjohncathedral.org/', null, 'America/Chicago', now()),
  ('Louisiana Orphan Train Museum', 'louisiana-orphan-train-museum', 'museums', 30.53158, -92.07467, 'Opelousas', 'LA', 'The museum preserves records and artifacts connected with more than 2,000 children sent from New York institutions to Louisiana families during the orphan-train era. It occupies a restored depot and keeps limited weekly hours.', 'limited', 'https://www.laorphantrainmuseum.com/', null, 'America/Chicago', now()),
  ('Longfellow-Evangeline State Historic Site', 'longfellow-evangeline-state-historic-site', 'folklore', 30.13554, -91.82263, 'St. Martinville', 'LA', 'This state site connects Acadian history with the literary legend of Evangeline popularized by Henry Wadsworth Longfellow. The grounds include a Creole plantation house and exhibits separating history from romanticized folklore.', 'open', 'https://www.lastateparks.com/historic-sites/longfellow-evangeline-state-historic-site', null, 'America/Chicago', now()),
  ('Evangeline Oak', 'evangeline-oak', 'folklore', 30.12202, -91.82756, 'St. Martinville', 'LA', 'A live oak on Bayou Teche is traditionally identified with the meeting place of Evangeline and Gabriel from Longfellow-inspired local lore. The story is literary rather than documented history, but the tree remains a major Acadiana folklore landmark.', 'open', 'https://www.stmartinville.org/', null, 'America/Chicago', now()),
  ('Acadian Memorial', 'acadian-memorial', 'museums', 30.12197, -91.82754, 'St. Martinville', 'LA', 'The Acadian Memorial commemorates Acadian refugees who arrived in Louisiana after deportation from Canada and includes a mural, genealogical resources and memorial installations. It stands beside the Evangeline Oak but is a distinct museum and remembrance site.', 'open', 'https://www.acadianmemorial.org/', null, 'America/Chicago', now()),
  ('Bayou Teche Museum', 'bayou-teche-museum', 'museums', 30.00508, -91.81741, 'New Iberia', 'LA', 'Interactive exhibits cover Bayou Teche culture, industry, music, food, local lore and Blue Dog artist George Rodrigue. Current public hours are Thursday through Saturday, with other visits available by appointment.', 'limited', 'https://bayoutechemuseum.org/', null, 'America/Chicago', now()),
  ('Rip Van Winkle Gardens — Jefferson Island', 'rip-van-winkle-gardens-jefferson-island', 'weird-history', 29.96997, -91.97333, 'New Iberia', 'LA', 'The gardens and Joseph Jefferson mansion sit atop a salt dome beside Lake Peigneur, whose 1980 drilling disaster famously drained the lake into an underground mine. The landscape combines theatrical history, geology and one of Louisiana''s strangest industrial accidents.', 'limited', 'https://www.ripvanwinklegardens.com/', null, 'America/Chicago', now()),
  ('Conrad Rice Mill / KONRIKO', 'conrad-rice-mill-konriko', 'roadside-oddities', 29.99783, -91.81094, 'New Iberia', 'LA', 'The historic Conrad Rice Mill preserves belt-driven equipment and the industrial process behind one of Louisiana''s staple foods. Tours operate on a schedule, so check current availability before routing.', 'limited', 'https://www.conradrice.com/', null, 'America/Chicago', now()),
  ('Shadows-on-the-Teche', 'shadows-on-the-teche', 'weird-history', 30.00439, -91.81566, 'New Iberia', 'LA', 'This 1830s house on Bayou Teche survives with extensive family records that document plantation life, slavery and the Civil War era. The National Trust operates it as a guided historic site rather than an unrestricted property.', 'limited', 'https://savingplaces.org/shadows-on-the-teche', null, 'America/Chicago', now()),
  ('Monsieur Jacques Frog Statue', 'monsieur-jacques-frog-statue', 'roadside-oddities', 30.24838, -92.26989, 'Rayne', 'LA', 'A giant tuxedoed frog tips his hat in the town that calls itself the Frog Capital of the World. The statue is an easy public photo stop and a strong visual anchor for Rayne''s frog-themed identity.', 'open', 'https://www.rayne.org/', null, 'America/Chicago', now()),
  ('Wrong Way Cemetery', 'wrong-way-cemetery', 'weird-history', 30.23191, -92.26871, 'Rayne', 'LA', 'St. Joseph Cemetery became a roadside curiosity because some graves are oriented in a direction visitors perceive as ''wrong'' compared with conventional expectations. It is an active burial ground, so visit respectfully during lawful hours.', 'limited', 'https://www.atlasobscura.com/places/wrong-way-cemetery', null, 'America/Chicago', now()),
  ('Gator Chateau', 'gator-chateau', 'roadside-oddities', 30.24742, -92.66688, 'Jennings', 'LA', 'This city-supported visitor center houses rescued alligators and gives visitors a close, controlled look at Louisiana''s signature reptile. Admission policies and animal-contact rules can change, so follow staff instructions.', 'open', 'https://cityofjennings.com/gator-chateau/', null, 'America/Chicago', now()),
  ('Swamp Pop Music Museum', 'swamp-pop-music-museum', 'museums', 30.6893, -92.27345, 'Ville Platte', 'LA', 'The museum documents swamp pop, the South Louisiana blend of rhythm and blues, country and Cajun influences that produced a distinctive regional sound. Displays focus on performers, recordings and local music infrastructure.', 'limited', 'https://www.evangelineparishtourism.org/', null, 'America/Chicago', now()),
  ('Fred''s Lounge', 'freds-lounge', 'weird-history', 30.63095, -92.41947, 'Mamou', 'LA', 'Fred''s is a tiny bar famous for live Cajun music and Saturday-morning broadcasts that turned it into a pilgrimage point for traditional music fans. Its operating window is narrow, so verify the current Saturday schedule before detouring.', 'limited', 'https://www.explorelouisiana.com/', null, 'America/Chicago', now()),
  ('Prairie Acadian Cultural Center', 'prairie-acadian-cultural-center', 'museums', 30.49315, -92.41731, 'Eunice', 'LA', 'This National Park Service center explores Cajun and Creole prairie culture through music, foodways, language and demonstrations. Live programs vary by day, making the calendar worth checking.', 'open', 'https://www.nps.gov/jela/planyourvisit/prairie-acadian-cultural-center.htm', null, 'America/Chicago', now()),
  ('Liberty Theatre', 'liberty-theatre', 'weird-history', 30.49306, -92.41611, 'Eunice', 'LA', 'The 1924 Liberty Theatre became famous for live Cajun and zydeco programming and is a landmark of Eunice''s music district. Restoration work has affected interior access, so OddWay should treat it as an exterior stop unless a current event explicitly opens the building.', 'roadside', 'https://www.eunice-la.com/', null, 'America/Chicago', now()),
  ('Gothic Hanging Jail — Beauregard Parish Jail', 'gothic-hanging-jail-beauregard-parish-jail', 'weird-history', 30.84625, -93.28821, 'DeRidder', 'LA', 'The 1914 Beauregard Parish Jail is a dramatic Gothic structure associated with the 1928 execution of two convicted killers, giving rise to its ''Hanging Jail'' nickname. Regular interior access is not guaranteed, so default to lawful exterior viewing unless an authorized tour is offered.', 'roadside', 'https://www.cityofderidder.org/', null, 'America/Chicago', now()),
  ('Brimstone Museum Complex', 'brimstone-museum-complex', 'museums', 30.23107, -93.37702, 'Sulphur', 'LA', 'Built around a relocated railroad depot, the Brimstone Museum interprets Sulphur''s industrial and community history and hosts changing exhibits. The neighboring Henning Cultural Center adds rotating art and regional programming.', 'open', 'https://brimstonemuseum.org/', null, 'America/Chicago', now()),
  ('Creole Nature Trail Adventure Point', 'creole-nature-trail-adventure-point', 'museums', 30.21137, -93.37689, 'Sulphur', 'LA', 'This visitor center uses interactive exhibits on alligators, marsh ecology, Cajun and Creole food and local music to prepare travelers for the Creole Nature Trail. It is a compact hands-on introduction to southwest Louisiana''s coastal weirdness.', 'open', 'https://www.visitlakecharles.org/creole-nature-trail/adventure-point/', null, 'America/Chicago', now()),
  ('International Petroleum Museum — Mr. Charlie', 'international-petroleum-museum-mr-charlie', 'roadside-oddities', 29.69122, -91.20971, 'Morgan City', 'LA', 'Mr. Charlie is a preserved offshore drilling rig that helped pioneer movable offshore oil production in the Gulf. Guided access turns a major piece of industrial infrastructure into a walk-through museum.', 'limited', 'https://www.rigmuseum.com/', null, 'America/Chicago', now()),
  ('Wedell-Williams Aviation & Cypress Sawmill Museum', 'wedell-williams-aviation-cypress-sawmill-museum', 'museums', 29.67738, -91.29232, 'Patterson', 'LA', 'One half of this state museum covers early Louisiana aviation and speed-record pilots, while the other preserves the machinery and labor history of cypress logging. The unlikely pairing makes it one of the state''s more eccentric museum combinations.', 'open', 'https://louisianastatemuseum.org/museum/wedell-williams-aviation-and-cypress-sawmill-museum', null, 'America/Chicago', now()),
  ('Marksville State Historic Site', 'marksville-state-historic-site', 'weird-history', 31.12463, -92.0479, 'Marksville', 'LA', 'This state site preserves prehistoric Native American earthworks associated with the Marksville culture and interprets regional archaeology. Stay on designated visitor paths and never climb or disturb protected mounds.', 'open', 'https://www.lastateparks.com/historic-sites/marksville-state-historic-site', null, 'America/Chicago', now()),
  ('First Bowie Knife Historical Marker', 'first-bowie-knife-historical-marker', 'weird-history', 31.12735, -92.066, 'Marksville', 'LA', 'A roadside marker commemorates the violent 1827 Sandbar Fight and the rise of the large fighting knife associated with Jim Bowie. The exact evolution of the ''Bowie knife'' is more complicated than the legend, but Marksville claims an important part of that story.', 'roadside', 'https://www.hmdb.org/', null, 'America/Chicago', now()),
  ('Forts Randolph & Buhlow State Historic Site', 'forts-randolph-buhlow-state-historic-site', 'weird-history', 31.32419, -92.44919, 'Pineville', 'LA', 'Earthworks and remains from two Civil War-era forts overlook the Red River near Alexandria. A visitor center and elevated walkways make the military landscape accessible without climbing fragile fortifications.', 'open', 'https://www.lastateparks.com/historic-sites/forts-randolph-buhlow-state-historic-site', null, 'America/Chicago', now()),
  ('Kent Plantation House', 'kent-plantation-house', 'roadside-oddities', 31.30611, -92.48361, 'Alexandria', 'LA', 'Kent House preserves one of central Louisiana''s oldest surviving Creole plantation dwellings along with reconstructed and moved outbuildings. Tours interpret building methods, household life and plantation labor.', 'limited', 'https://www.kenthouse.org/', null, 'America/Chicago', now()),
  ('Hotel Bentley', 'hotel-bentley', 'haunted', 31.31194, -92.445, 'Alexandria', 'LA', 'The grand 1908 Hotel Bentley has long accumulated stories involving wartime guests, political figures and reported paranormal activity. It is an operating hotel, so ghost lore should not interfere with normal guest areas or private rooms.', 'open', 'https://www.visithotelbentley.com/', null, 'America/Chicago', now()),
  ('Louisiana Maneuvers & Military Museum', 'louisiana-maneuvers-military-museum', 'weird-history', 31.3333, -92.4105, 'Pineville', 'LA', 'Located at Camp Beauregard, this Louisiana National Guard museum interprets the massive pre-World War II Louisiana Maneuvers and later military history. Because it is on a Guard installation, check current public hours and identification requirements before visiting.', 'limited', 'https://geauxguardmuseums.com/', null, 'America/Chicago', now()),
  ('Poverty Point World Heritage Site', 'poverty-point-world-heritage-site', 'weird-history', 32.63622, -91.40503, 'Pioneer', 'LA', 'Poverty Point preserves a vast complex of Indigenous earthworks built more than three thousand years ago by hunter-gatherers who organized long-distance trade and monumental construction. It is a UNESCO World Heritage Site and one of Louisiana''s most important archaeological stops.', 'open', 'https://www.lastateparks.com/historic-sites/poverty-point-world-heritage-site', null, 'America/Chicago', now()),
  ('Germantown Colony Museum', 'germantown-colony-museum', 'weird-history', 32.70006, -93.23133, 'Minden', 'LA', 'The museum preserves surviving buildings from a nineteenth-century communal religious settlement founded by German immigrants. Current state museum hours are limited to specific days, so verify before making the rural detour.', 'limited', 'https://www.sos.la.gov/HistoricalResources/VisitMuseums/Pages/GermantownColonyMuseum.aspx', null, 'America/Chicago', now()),
  ('Bonnie & Clyde Ambush Museum', 'bonnie-clyde-ambush-museum', 'weird-history', 32.54508, -93.05313, 'Gibsland', 'LA', 'This small museum near the former cafe where Bonnie Parker and Clyde Barrow stopped before their deaths is packed with photographs, replicas and ambush-related memorabilia. It is intentionally focused on one of America''s most mythologized crime stories.', 'open', 'https://www.explorelouisiana.com/', null, 'America/Chicago', now()),
  ('Bonnie & Clyde Ambush Site', 'bonnie-clyde-ambush-site', 'weird-history', 32.53146, -93.06446, 'Gibsland', 'LA', 'A roadside marker identifies the area where law officers ambushed Bonnie Parker and Clyde Barrow on May 23, 1934. Pull completely off the roadway only where lawful and safe, and never stand in traffic to recreate photographs.', 'roadside', 'https://www.hmdb.org/', null, 'America/Chicago', now()),
  ('Shreveport Water Works Museum', 'shreveport-water-works-museum', 'roadside-oddities', 32.5174, -93.75722, 'Shreveport', 'LA', 'The preserved McNeill Street water plant contains historic steam pumps and machinery from Shreveport''s early municipal water system. The industrial complex is unusually intact, but public access depends on current museum operations.', 'limited', 'https://shreveportwaterworks.org/', null, 'America/Chicago', now()),
  ('ART the Dalmatian', 'art-the-dalmatian', 'roadside-oddities', 32.5106, -93.7502, 'Shreveport', 'LA', 'A roughly twenty-foot spotted dog sculpture by artist William Joyce guards Central ARTSTATION, with its spots recognizing arts supporters. The outdoor work is visible from the public arts district even when the building is closed.', 'open', 'https://www.shrevearts.org/', null, 'America/Chicago', now()),
  ('Shreveport Municipal Auditorium', 'shreveport-municipal-auditorium', 'weird-history', 32.50808, -93.75319, 'Shreveport', 'LA', 'This Art Deco auditorium is a cornerstone of Louisiana Hayride history and helped launch performers including Elvis Presley. It remains an active event venue, so interior access depends on tours, shows and the building calendar.', 'limited', 'https://www.shreveportmunicipalauditorium.com/', null, 'America/Chicago', now()),
  ('Spring Street Historical Museum', 'spring-street-historical-museum', 'haunted', 32.51441, -93.74601, 'Shreveport', 'LA', 'The museum occupies the 1865 Tally''s Bank building, one of downtown Shreveport''s oldest surviving structures. Staff and local storytellers have also attached ghost reports to the building, adding paranormal lore to its architectural history.', 'limited', 'https://www.visitshreveportbossier.org/', null, 'America/Chicago', now()),
  ('Louisiana State Exhibit Museum', 'louisiana-state-exhibit-museum', 'museums', 32.4817, -93.7856, 'Shreveport', 'LA', 'This circular 1939 museum is filled with large WPA-era dioramas showing Louisiana agriculture, industry and culture in miniature. The building itself and the old-fashioned immersive exhibits make it unusually distinctive.', 'open', 'https://www.laexhibitmuseum.org/', null, 'America/Chicago', now()),
  ('Barksdale Global Power Museum', 'barksdale-global-power-museum', 'weird-history', 32.51068, -93.68092, 'Bossier City', 'LA', 'Aircraft and exhibits at Barksdale Air Force Base trace strategic bombing and U.S. Air Force history. Since the museum is on an active military installation, visitors must follow current base-access and identification procedures.', 'limited', 'https://www.barksdaleglobalpowermuseum.com/', null, 'America/Chicago', now()),
  ('Biedenharn Museum & Gardens', 'biedenharn-museum-gardens', 'museums', 32.5197, -92.13132, 'Monroe', 'LA', 'The museum preserves the home of Joseph Biedenharn, credited with first bottling Coca-Cola commercially, alongside Bible and regional collections. That mix of soft-drink history, formal gardens and religious artifacts makes it an unexpectedly eclectic stop.', 'open', 'https://www.bmuseum.org/', null, 'America/Chicago', now()),
  ('Chennault Aviation & Military Museum', 'chennault-aviation-military-museum', 'weird-history', 32.51183, -92.05325, 'Monroe', 'LA', 'Named for General Claire Chennault, the museum explores the Flying Tigers, Selman Field navigation school and regional military history. Aircraft, uniforms and personal artifacts connect northeast Louisiana directly to global wartime stories.', 'open', 'https://chennaultmuseum.org/', null, 'America/Chicago', now()),
  ('Louisiana Political Museum & Hall of Fame', 'louisiana-political-museum-hall-of-fame', 'museums', 31.92678, -92.63538, 'Winnfield', 'LA', 'Louisiana''s famously colorful political history gets its own museum in the hometown region of several major politicians. Campaign objects, memorabilia and exhibits turn state politics into a specialized museum subject.', 'open', 'https://lapoliticalmuseum.com/', null, 'America/Chicago', now()),
  ('Louisiana Sports Hall of Fame & Northwest Louisiana History Museum', 'louisiana-sports-hall-of-fame-northwest-louisiana-history-museum', 'roadside-oddities', 31.76345, -93.08845, 'Natchitoches', 'LA', 'A highly sculptural contemporary building houses both Louisiana sports history and exhibits on the cultures of northwest Louisiana. Its flowing interior geometry makes the architecture as memorable as the collections.', 'open', 'https://louisianastatemuseum.org/museum/louisiana-sports-hall-fame-northwest-louisiana-history-museum', null, 'America/Chicago', now()),
  ('Fort St. Jean Baptiste State Historic Site', 'fort-st-jean-baptiste-state-historic-site', 'museums', 31.75127, -93.08809, 'Natchitoches', 'LA', 'A reconstruction of the early French fort on Cane River uses period methods and materials to interpret colonial life and regional trade. The recreated stockade gives travelers a rare immersive stop from Louisiana''s pre-American period.', 'open', 'https://www.lastateparks.com/historic-sites/fort-st-jean-baptiste-state-historic-site', null, 'America/Chicago', now()),
  ('Fort Jesup State Historic Site', 'fort-jesup-state-historic-site', 'weird-history', 31.5274, -93.4024, 'Many', 'LA', 'Fort Jesup was established by Zachary Taylor near the old borderlands between the United States and Spanish Texas. Current state schedules can place the site on appointment-only access, so call before making a dedicated detour.', 'limited', 'https://www.lastateparks.com/historic-sites/fort-jesup-state-historic-site', null, 'America/Chicago', now()),
  ('Los Adaes State Historic Site', 'los-adaes-state-historic-site', 'roadside-oddities', 31.7085, -93.29323, 'Robeline', 'LA', 'Los Adaes was once the capital of Spanish Texas and a frontier settlement facing French Louisiana. Archaeological remains rather than a recreated town survive today, and public schedules can be seasonal or limited.', 'limited', 'https://www.lastateparks.com/historic-sites/los-adaes-state-historic-site', null, 'America/Chicago', now()),
  ('Oakland Plantation — Cane River Creole NHP', 'oakland-plantation-cane-river-creole-nhp', 'weird-history', 31.66561, -93.00359, 'Natchez', 'LA', 'Oakland preserves a remarkably complete plantation complex with quarters, store, barns and the main house, allowing the National Park Service to interpret generations of Creole plantation life and enslaved labor. Building access varies by day even when grounds are open.', 'limited', 'https://www.nps.gov/cari/planyourvisit/oakland-plantation.htm', null, 'America/Chicago', now()),
  ('Magnolia Plantation — Cane River Creole NHP', 'magnolia-plantation-cane-river-creole-nhp', 'weird-history', 31.54921, -92.94157, 'Derry', 'LA', 'National Park Service holdings at Magnolia preserve slave/tenant cabins, a plantation store, gin barn and other structures within the Cane River landscape. The main house remains privately owned and is not open to the public, so stay strictly within NPS visitor areas.', 'limited', 'https://www.nps.gov/cari/planyourvisit/magnolia-plantation.htm', null, 'America/Chicago', now()),
  ('Melrose Plantation', 'melrose-plantation', 'roadside-oddities', 31.59998, -92.96574, 'Melrose', 'LA', 'Melrose developed from a complex Creole community and later became an arts center associated with Clementine Hunter, whose murals survive in the African House. Guided access links plantation history, architecture and outsider art in one site.', 'limited', 'https://www.melroseonthecane.com/', null, 'America/Chicago', now()),
  ('Mansfield State Historic Site', 'mansfield-state-historic-site', 'weird-history', 32.01092, -93.66495, 'Mansfield', 'LA', 'This battlefield preserves the site of the 1864 Battle of Mansfield, where Confederate forces halted the Union Red River Campaign. Trails, monuments and a museum interpret a major Civil War battle west of the Mississippi.', 'open', 'https://www.lastateparks.com/historic-sites/mansfield-state-historic-site', null, 'America/Chicago', now()),
  ('Rebel State Historic Site', 'rebel-state-historic-site', 'weird-history', 31.74963, -93.42052, 'Marthaville', 'LA', 'The site evolved from a Confederate memorial into a broader museum of northwestern Louisiana culture and country music. Current state schedules may require appointment access, so check before routing.', 'limited', 'https://www.lastateparks.com/historic-sites/rebel-state-historic-site', null, 'America/Chicago', now()),
  ('Louisiana State Oil & Gas Museum', 'louisiana-state-oil-gas-museum', 'roadside-oddities', 32.74128, -93.97088, 'Oil City', 'LA', 'Located in a town literally named for petroleum, this museum uses photographs, machinery, rigs and life-size scenes to tell the story of Louisiana''s early oil boom. Outdoor equipment around the old depot extends the exhibits beyond the museum building.', 'open', 'https://www.sos.la.gov/museums/louisiana-state-oil-and-gas-museum', null, 'America/Chicago', now()),
  ('Louisiana Military Museum', 'louisiana-military-museum', 'weird-history', 32.52925, -92.63366, 'Ruston', 'LA', 'This specialized museum covers conflicts from the Civil War through modern deployments with deactivated weapons, uniforms, diaries, medals and heavy equipment. Personal artifacts keep the collection from feeling like only a display of hardware.', 'open', 'https://www.sos.la.gov/', null, 'America/Chicago', now()),
  ('Delta Music Museum', 'delta-music-museum', 'weird-history', 31.62955, -91.55355, 'Ferriday', 'LA', 'Ferriday''s free Delta Music Museum celebrates the region''s outsized influence on blues, gospel, country, rockabilly and rock and roll. Exhibits include performers such as Jerry Lee Lewis, Mickey Gilley and other musicians tied to the Mississippi Delta corridor.', 'open', 'https://deltamusicmuseum.com/', null, 'America/Chicago', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as louisiana from public.stops where state = 'LA';
